import fs from 'fs';
function parse(s){
  const rows=[]; let i=0;
  while(i<s.length){
    const row=[]; let cur=''; let inQ=false;
    for(;i<s.length;i++){
      const c=s[i];
      if(inQ){
        if(c==='"'){ if(s[i+1]==='"'){cur+='"';i++;} else inQ=false; }
        else cur+=c;
      } else {
        if(c==='"') inQ=true;
        else if(c===','){ row.push(cur); cur=''; }
        else if(c==='\r'){ }
        else if(c==='\n'){ row.push(cur); cur=''; i++; break; }
        else cur+=c;
      }
    }
    if(row.length) rows.push(row);
  }
  return rows;
}
const rows=parse(fs.readFileSync('meetings-07-simple.p01.csv','utf8'));
rows.shift();
const over={
  23:["L3","'please add it and make it gold': the coordination gives 'and' three conjuncts and holds 'Mihai asked for a shared Team lunches calendar' as one of them, though no word joins that clause to the command."],
  110:["L3","'please call Ana Annie in the people list': 'Ana' and 'Annie' are written as one nominal with 'Annie' as head, merging the person 'call' acts on with the name given to her."]
};
const lines=rows.map(r=>{
  const n=Number(r[0]);
  const v=over[n]||["L8",""];
  return JSON.stringify({n,grade:v[0],note:v[1]});
});
fs.writeFileSync('meetings-07-simple.p01.verdicts.jsonl',lines.join('\n')+'\n');
console.log('rows',rows.length,'written',lines.length);
console.log(lines.filter(l=>!l.includes('"L8"')).join('\n'));
